```python
import random

def generate_palindrome(length):
    if length % 2 == 1:
        half_length = (length - 1) // 2
    else:
        half_length = length // 2

    # Generate a random string of characters
    random_string = ''.join(random.choices('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789', k=half_length))

    if length % 2 == 1:
        return random_string + random_string[::-1] + random.choice('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789')
    else:
        return random_string + random_string[::-1]

print(generate_palindrome(580))
```

